// Extract and sanitize user message
const update = $input.first().json;
const message = update.message || {};
const chat = message.chat || {};
const from = message.from || {};

return [{
  json: {
    chatId: chat.id,
    userId: from.id,
    username: from.username || from.first_name || 'User',
    text: message.text || '',
    messageId: message.message_id,
    timestamp: new Date(message.date * 1000).toISOString()
  }
}];

// Format final response for Telegram
const agentOutput = $input.first().json;
const context = $('Extract Message').first().json;

let replyText = agentOutput.output || agentOutput.text || agentOutput.response || 'I apologize, I could not process your request at this time.';

// Append property listings if available
const propertyData = $('Search Properties').all()[0];
if (propertyData && propertyData.json && Array.isArray(propertyData.json.properties) && propertyData.json.properties.length > 0) {
  replyText += '\n\n🏢 *Available Properties:*\n';
  propertyData.json.properties.slice(0, 5).forEach((p, i) => {
    replyText += `\n${i+1}. ${p.title || 'Property'}\n` +
                 `   📍 ${p.location || 'Dubai'}\n` +
                 `   💰 AED ${(p.price || 0).toLocaleString()}\n` +
                 `   🛏 ${p.bedrooms || 'N/A'} BR | 🏠 ${p.type || 'N/A'}\n`;
  });
}

return [{
  json: {
    chatId: context.chatId,
    userId: context.userId,
    username: context.username,
    text: context.text,
    messageId: context.messageId,
    output: replyText
  }
}];
